-- Development seed: original AUREN sample catalogue (placeholder products).
-- Generated by scripts/generate-seed.ts. Safe to re-run: skips products that already exist.
select set_config('app.inventory_write', 'on', true);


-- Velocity Runner X
do $$
declare p_velocity_runner_x uuid; v_color uuid; v_variant uuid; v_asset uuid; v_model uuid;
begin
  if exists (select 1 from public.products where slug = 'velocity-runner-x') then return; end if;
  values ('Velocity Runner X', 'velocity-runner-x', 'AU-VRX', (select id from public.categories where slug = 'running'), 'unisex', 'A high-cushion daily runner with a breathable engineered-knit upper and a rocker-shaped foam midsole.', 'Velocity Runner X pairs a soft engineered-knit upper with a tall foam midsole and a gentle toe spring for smooth heel-to-toe transitions.

- Engineered knit upper with a padded collar
- Dual-density foam midsole with a pronounced rocker
- Rubber outsole in high-wear zones
- Reflective-look heel tab', 899900, 749900, 'draft', now() - interval '9 days', true, false, true, true, array['running', 'cushioned', 'knit', 'daily-trainer']::text[], v_model, (select id from public.size_guides where is_default limit 1), 'Velocity Runner X — Volt Night', 'A high-cushion daily runner with a breathable engineered-knit upper and a rocker-shaped foam midsole.')
  returning id into p_velocity_runner_x;
  update public.products set status = 'published' where id = p_velocity_runner_x;
end $$;

